DAS01:
\sect{发射链与瑞利回波（图中逐段标号）}
\begin{align*}
 B_0&=A_0e^{i\phi_L(T+u)},\quad E_j=B_je^{i\omega_0u},\\
 B_1&=t_I B_0,\qquad B_2=p(u)e^{i\Omega_Au}B_1,\\
 B_3&=\sqrt G B_2,\qquad B_p=h_B*B_3,\\
 B_F&=t_{12}B_p,\quad B_{\rm bs}=\Hh[B_F],\\
 B_r&=t_{23}B_{\rm bs}=t_{23}\sum_j r_j B_F(u-\tau_j)e^{i\delta\Phi_j(T)}.
\end{align*}
这里 $\tau_j=2z_j/v_g$；$p$ 是场门函数；$G$ 为功率增益。$h_B$ 为滤波器的复基带冲激响应，$*$ 表示卷积。

\sect{光电流与可观测量}
令 $q_j=r_jB_F(u-\tau_j)e^{i\delta\Phi_j}$，则
\begin{align*}
 i&=\R|B_r|^2\\
  &=\R|t_{23}|^2\left[\sum_j|q_j|^2+2\sum_{j<k}\Re(q_jq_k^*)\right],\\
 D(u,T)&=i(u,T)-i(u,T_0),\qquad z=\frac{v_gu}{2}.
\end{align*}
\sect{解释与适用边界}
交叉项含 $\cos[\delta\Phi_j-\delta\Phi_k+\text{静态相位}]$。强度差可定位振动，但对相位一般是非线性的；单独测量强度不能直接套用线性的相位--应变公式。
\[\Delta z\simeq\frac{v_g\tau_p}{2},\qquad f_{\rm rep}\lesssim\frac{v_g}{2L}.\]
这里 $\tau_p$ 是脉宽，$L$ 为感测长度；$u$ 已扣除固定系统延迟。

DAS03:
\sect{探测光与本振（所有光场共用 $e^{i\omega_0u}$）}
\begin{align*}
 B_0&=A_0e^{i\phi_L(T+u)},\quad B_1=t_I B_0,\\
 B_S&=s_S B_1,\quad B_{L0}=s_L B_1,\\
 B_{L1}&=t_{\rm PC}B_{L0},\quad B_L=t_VB_{L1},\\
 B_2&=p(u)B_S,\quad B_3=\sqrt G B_2,\\
 B_p&=h_B*B_3,\quad B_F=t_{12}B_p,\\
 B_{\rm bs}&=\Hh[B_F],\quad B_r=t_{23}B_{\rm bs}.
\end{align*}
各系数可为复数；PC 在此表示匹配偏振后的标量投影。延迟本振还需将 $B_1(u)$ 换为 $B_1(u-\tau_L)$。
\note{IM 采用无频移门控；$\Omega_A=0$。若使用 AOM，必须补偿本振频移才能得到零差。}

\sect{四个光输出与两路差分电流}
采用下列功率归一化的理想混频器矩阵：
\begin{align*}
 B_{I\pm}&=(B_r\pm B_L)/2,\\
 B_{Q\pm}&=(B_r\pm iB_L)/2,\\
 I&=\R(|B_{I+}|^2-|B_{I-}|^2)=\R\Re(B_rB_L^*),\\
 Q&=\R(|B_{Q+}|^2-|B_{Q-}|^2)=\R\Im(B_rB_L^*),\\
 \widehat C&=(I+iQ)/\R,\qquad\phi=\atan(Q,I).
\end{align*}
\sect{相位--应变换算}

\[\Delta_T\phi_g=\Delta_T\unwrap\arg\!\left[C(z+L_g,T)C^*(z,T)\right],
\qquad\overline{\Delta\epsilon}=-\frac{\Delta_T\phi_g}{K_\epsilon L_g}.\]

四端口总光功率等于 $|B_r|^2+|B_L|^2$。实际接收器需校正 I/Q 偏置、增益差和正交误差。

DAS04:
\sect{发射链与瑞利回波（图中逐段标号）}
\begin{align*}
 B_0&=A_0e^{i\phi_L(T+u)},\quad E_j=B_je^{i\omega_0u},\\
 B_1&=t_I B_0,\qquad B_2=p(u)e^{i\Omega_Au}B_1,\\
 B_3&=\sqrt G B_2,\qquad B_p=h_B*B_3,\\
 B_F&=t_{12}B_p,\quad B_{\rm bs}=\Hh[B_F],\\
 B_r&=t_{23}B_{\rm bs}=t_{23}\sum_j r_j B_F(u-\tau_j)e^{i\delta\Phi_j(T)}.
\end{align*}
这里 $\tau_j=2z_j/v_g$；$p$ 是场门函数；$G$ 为功率增益。$h_B$ 为滤波器的复基带冲激响应，$*$ 表示卷积。

\sect{分光与两臂的光场}
\[B_{a0}=s_a B_r,\quad B_{b0}=s_b B_r,\quad
B_a=aB_r(u-\tau_a),\quad B_b=bB_r(u-\tau_b).\]
$a,b$ 含分光、臂损耗及 $e^{-i\omega_0\tau_{a,b}}$；$\tau_d=\tau_b-\tau_a$。

\sect{三个光输出及相位解调}
\begin{align*}
 B_{d,k}&=(B_a+e^{i\theta_k}B_b)/\sqrt3,\quad\theta_k=2\pi k/3,\\
 i_k&=\R|B_{d,k}|^2=I_0+V\cos(\phi-\theta_k),\quad k=0,1,2,\\
 I_0&=\R(|B_a|^2+|B_b|^2)/3,\quad V=2\R|B_aB_b|/3,\\
 \phi&=\arg(B_aB_b^*)\\
 &=\atan\!\left(\sqrt3(i_1-i_2),\;2i_0-i_1-i_2\right).
\end{align*}
\sect{延迟与标距}
\[L_g=\frac{v_g\tau_d}{2},\qquad
\overline{\Delta\epsilon}=-\frac{\Delta_T\unwrap\phi}{K_\epsilon L_g}.\]
短延迟臂对应较远位置，长延迟臂对应较近位置。式中输出顺序与图中 $B_{d,0},B_{d,1},B_{d,2}$ 一一对应。实际耦合器需校准三通道增益与非理想相移。

DAS05:
\sect{发射与反射臂：每个方向的场}
发射链 $B_0\to B_1\to B_2\to B_3\to B_p\to B_F\to B_r$ 与路线 1 相同；接收 ISO 后 $B_{r0}=t_{Ir}B_r$。设 2×2 耦合器的透射、耦合振幅为 $t,c$：
\begin{align*}
 B_{a+}&=tB_{r0},\qquad B_{b+}=cB_{r0},\\
 B_{a-}&=\rho_a e^{-i\omega_0\tau_a}B_{a+}(u-\tau_a),\\
 B_{b-}&=\rho_b e^{-i\omega_0\tau_b}B_{b+}(u-\tau_b)e^{iC\cos x},\\
 B_D&=cB_{a-}+tB_{b-}=B_a+B_be^{iC\cos x},\\
 x&=\omega_c(T+u)+\psi_c.
\end{align*}
$\rho_{a,b}$ 含双程臂损耗及 FRM 反射。$B_a=cB_{a-}$；$B_b=tB_{b-}e^{-iC\cos x}$。理想无损耦合器可取 $t=1/\sqrt2,c=i/\sqrt2$。

\sect{探测电流与 PGC 谐波}
\begin{align*}
 i&=\R|B_D|^2=I_0+V\cos(\phi-C\cos x),\\
 \phi&=\arg(B_aB_b^*),\quad V=2\R|B_aB_b|,\\
 h_1&=2VJ_1(C)\sin\phi,\qquad h_2=-2VJ_2(C)\cos\phi,\\
 \phi&=\atan\!\left(\frac{h_1}{2J_1(C)},\;-\frac{h_2}{2J_2(C)}\right).
\end{align*}
$h_n$ 为 $\cos(nx)$ 的傅里叶系数；$J_n$ 是第一类贝塞尔函数。同步解调并低通后得到这些系数。
\sect{双程延迟与应变}
\[L_g=\frac{v_g(\tau_b-\tau_a)}{2}=\Delta\ell,\qquad
\overline{\Delta\epsilon}=-\frac{\Delta_T\unwrap\phi}{K_\epsilon L_g}.\]
$\Delta\ell$ 是物理臂长差（两臂群速度相同）。$C$ 表示有效双程调制深度；只有两次通过 PM 的驱动相位近似相同，才有 $C\simeq2C_{\rm single}$。

DAS06:
\sect{双脉冲的每一光支路}
\begin{align*}
 B_1&=t_I B_0,\quad B_{a0}=s_aB_1,\quad B_{b0}=s_bB_1,\\
 B_A&=a_Ap(u)e^{i\Omega_1u}B_{a0},\\
 B_B&=a_Bp(u-\Delta T)e^{i\Omega_2u+i\theta}B_{b0},\\
 B_{\rm pair}&=c_AB_A+c_BB_B,\quad B_3=\sqrt G B_{\rm pair},\\
 B_p&=h_B*B_3,\quad B_F=t_{12}B_p,\\
 B_{\rm bs}&=\Hh[B_F],\quad B_r=t_{23}B_{\rm bs}=B_{r1}+B_{r2}.
\end{align*}
线性算子允许分别对 $B_A,B_B$ 求回波后相加。$c_A,c_B$ 是合束系数；$\theta$ 是锁定的 RF 相对初相。令 $B_{r\ell}=A_{r\ell}e^{i\Omega_\ell u}$。

\sect{探测与拍频相位}
\begin{align*}
 i&=\R(|A_{r1}|^2+|A_{r2}|^2)\\
 &\quad+2\R\Re(A_{r1}A_{r2}^*e^{i\Delta\Omega u}),\\
 \Delta\Omega&=\Omega_1-\Omega_2,\\
 \widehat C&=\LPF[i e^{-i\Delta\Omega u}]/\R,\\
 \phi&=\arg\widehat C,\qquad L_g\simeq v_g\Delta T/2.
\end{align*}
\[\overline{\Delta\epsilon}=-\frac{\Delta_T\unwrap\phi}{K_\epsilon L_g}.\]
在同一接收时刻，第一脉冲来自较远散射区，延后发射的第二脉冲来自较近散射区；拍频项保存两者的相位差。解调需抑制直流和负频项，并选择回波重叠区。
\note{两支路的频率差也引入固定传播相位，纳入静态校准；当频移远小于光频时，相位--应变系数可用共同的 $K_\epsilon$。}

DAS07:
\sect{啁啾光与脉冲门控}
\begin{align*}
 B_0&=A_0e^{i\pi\kappa u^2+i\phi_L(T+u)},\\
 \nu(u)&=\nu_0+\kappa u,\quad [\kappa]={\rm Hz/s},\\
 B_1&=t_I B_0,\quad B_2=\sqrt{G_{\rm SOA}}p(u)B_1,\\
 B_3&=\sqrt G B_2,\quad B_p=h_B*B_3,\\
 B_F&=t_{12}B_p,\quad B_{\rm bs}=\Hh[B_F],\\
 B_r&=t_{23}B_{\rm bs},\qquad I_T(u)=\R|B_r|^2.
\end{align*}
完整光场为 $E_0=B_0e^{i\omega_0u}$；SOA 完成场门控与增益。电流斜坡施加于 LD，使同一个脉冲具有线性瞬时频率。

\sect{明确平移符号的相关解调}
在位置窗口 $W_z$ 内定义
\begin{align*}
 I_T(u)&\simeq I_0(u+\delta u),\\
 \delta u&=\arg\max_d\int_{W_z}I_T(u)I_0(u+d)\,du,\\
 \Delta\nu_R&=-\kappa\delta u,\\
 \frac{\Delta\nu_R}{\nu_0}&=-\xi\Delta\epsilon-C_{\mathcal T}\Delta\mathcal T,\quad\xi=1-p_e.
\end{align*}
\sect{温度固定时的应变}
\[\boxed{\Delta\epsilon=\frac{\kappa\delta u}{\nu_0\xi}}\]
上述符号对应图中的升频啁啾与 $I_0(u+d)$ 相关约定。$\Delta\mathcal T$ 为温度变化，$C_{\mathcal T}$ 为温度系数；温度与应变未经额外观测无法独立分离。
\note{模型要求窗口内频谱近似刚性平移、啁啾可校准，且迹线保持足够相关；这里恢复的是局部应变变化。}

DAS08:
\sect{第 $m$ 个频率的完整光链}
\begin{align*}
 B_1&=t_I B_0,\quad \nu_m=\nu_0+m\delta\nu,\\
 B_{\nu,m}&=t_{\rm SSB}B_1e^{i2\pi m\delta\nu u},\\
 B_{2,m}&=p(u)B_{\nu,m},\quad B_{3,m}=\sqrt G B_{2,m},\\
 B_{p,m}&=h_B*B_{3,m},\quad B_{F,m}=t_{12}B_{p,m},\\
 B_{{\rm bs},m}&=\mathcal H_{T,m}[B_{F,m}],\quad
 B_{r,m}=t_{23}B_{{\rm bs},m},\\
 I_T(z,\nu_m)&=\R|B_{r,m}(u_z,T)|^2,\quad u_z=2z/v_g.
\end{align*}
单边带 EOM 实现频移，IM 单独门控。跨频率扫描时 $r_{j,m}$ 和 $\delta\Phi_{j,m}$ 随 $\nu_m$ 变化，不能假定各频率共享完全相同的复散射系数。

\sect{局部谱移与应变}
\begin{align*}
 I_T(z,\nu)&\simeq I_0(z,\nu-\Delta\nu_R),\\
 \Delta\nu_R&=\arg\max_d\int I_T(z,\nu)I_0(z,\nu-d)\,d\nu,\\
 \frac{\Delta\nu_R}{\nu_0}&=-\xi\Delta\epsilon-C_{\mathcal T}\Delta\mathcal T,\\
 \Delta\epsilon\big|_{\Delta\mathcal T=0}&=-\frac{\Delta\nu_R}{\nu_0\xi}.
\end{align*}
\sect{频率维采样的代价}
\[f_{\rm update}\lesssim\frac{f_{\rm rep}}{N_\nu},\qquad
f_{\rm acoustic}<f_{\rm update}/2.\]
$N_\nu$ 为一轮扫描的频率点数；上式适用于串行采集、每频率一个脉冲的常规方案。扫描期间应变需近似不变，否则谱图产生运动畸变。
\note{此图是可实现的通用频率步进拓扑；论文中的具体频移模块与高速复用细节可能不同。}
